CREATE TABLE languages ( code TEXT PRIMARY KEY, name TEXT NOT NULL, is_default INTEGER NOT NULL DEFAULT 0 ); INSERT INTO languages (code, name, is_default) VALUES ('en', 'English', 1), ('sq', 'Shqip', 0); CREATE TABLE users ( id INTEGER PRIMARY KEY, email TEXT NOT NULL UNIQUE COLLATE NOCASE, display_name TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'assistant' CHECK (role IN ('owner', 'assistant')), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) ); CREATE TABLE media ( id INTEGER PRIMARY KEY, r2_key TEXT NOT NULL UNIQUE, filename TEXT NOT NULL, mime TEXT NOT NULL, bytes INTEGER NOT NULL, width INTEGER, height INTEGER, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) ); CREATE TABLE media_i18n ( media_id INTEGER NOT NULL REFERENCES media(id) ON DELETE CASCADE, lang TEXT NOT NULL REFERENCES languages(code), alt TEXT NOT NULL DEFAULT '', caption TEXT NOT NULL DEFAULT '', PRIMARY KEY (media_id, lang) ); CREATE TABLE tags ( id INTEGER PRIMARY KEY, kind TEXT NOT NULL CHECK (kind IN ('region', 'topic')), key TEXT NOT NULL, UNIQUE (kind, key) ); CREATE TABLE tag_i18n ( tag_id INTEGER NOT NULL REFERENCES tags(id) ON DELETE CASCADE, lang TEXT NOT NULL REFERENCES languages(code), name TEXT NOT NULL, PRIMARY KEY (tag_id, lang) ); CREATE TABLE categories ( id INTEGER PRIMARY KEY, key TEXT NOT NULL UNIQUE, sort_order INTEGER NOT NULL DEFAULT 0 ); CREATE TABLE category_i18n ( category_id INTEGER NOT NULL REFERENCES categories(id) ON DELETE CASCADE, lang TEXT NOT NULL REFERENCES languages(code), name TEXT NOT NULL, slug TEXT NOT NULL, PRIMARY KEY (category_id, lang), UNIQUE (lang, slug) ); CREATE TABLE tours ( id INTEGER PRIMARY KEY, key TEXT NOT NULL UNIQUE, hours INTEGER, price_from INTEGER, max_guests INTEGER CHECK (max_guests >= 1), published INTEGER NOT NULL DEFAULT 0, featured INTEGER NOT NULL DEFAULT 0, sort_order INTEGER NOT NULL DEFAULT 0, cover_media_id INTEGER REFERENCES media(id) ON DELETE SET NULL, scene TEXT, seed INTEGER, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) ); CREATE TABLE tour_i18n ( tour_id INTEGER NOT NULL REFERENCES tours(id) ON DELETE CASCADE, lang TEXT NOT NULL REFERENCES languages(code), slug TEXT NOT NULL, title TEXT NOT NULL, short TEXT NOT NULL DEFAULT '', ready INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (tour_id, lang), UNIQUE (lang, slug) ); CREATE TABLE tour_tags ( tour_id INTEGER NOT NULL REFERENCES tours(id) ON DELETE CASCADE, tag_id INTEGER NOT NULL REFERENCES tags(id) ON DELETE CASCADE, PRIMARY KEY (tour_id, tag_id) ); CREATE TABLE tour_media ( tour_id INTEGER NOT NULL REFERENCES tours(id) ON DELETE CASCADE, media_id INTEGER NOT NULL REFERENCES media(id) ON DELETE CASCADE, sort_order INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (tour_id, media_id) ); CREATE TABLE tour_steps ( id INTEGER PRIMARY KEY, tour_id INTEGER NOT NULL REFERENCES tours(id) ON DELETE CASCADE, sort_order INTEGER NOT NULL DEFAULT 0, time TEXT NOT NULL DEFAULT '' ); CREATE TABLE tour_step_i18n ( step_id INTEGER NOT NULL REFERENCES tour_steps(id) ON DELETE CASCADE, lang TEXT NOT NULL REFERENCES languages(code), text TEXT NOT NULL, PRIMARY KEY (step_id, lang) ); CREATE TABLE tour_included ( id INTEGER PRIMARY KEY, tour_id INTEGER NOT NULL REFERENCES tours(id) ON DELETE CASCADE, sort_order INTEGER NOT NULL DEFAULT 0 ); CREATE TABLE tour_included_i18n ( included_id INTEGER NOT NULL REFERENCES tour_included(id) ON DELETE CASCADE, lang TEXT NOT NULL REFERENCES languages(code), text TEXT NOT NULL, PRIMARY KEY (included_id, lang) ); CREATE TABLE articles ( id INTEGER PRIMARY KEY, status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'scheduled', 'published')), publish_date TEXT, category_id INTEGER REFERENCES categories(id) ON DELETE SET NULL, author_id INTEGER REFERENCES users(id) ON DELETE SET NULL, cover_media_id INTEGER REFERENCES media(id) ON DELETE SET NULL, tour_id INTEGER REFERENCES tours(id) ON DELETE SET NULL, group_size INTEGER, group_from TEXT, scene TEXT, seed INTEGER, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) );
